const paths={layers:'<path d="m12 3 10 5-10 5L2 8z"/><path d="m2 12 10 5 10-5M2 16l10 5 10-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>',checklist:'<path d="M9 6h11M9 12h11M9 18h11m-17-12 1 1 2-2m-3 7 1 1 2-2m-3 7 1 1 2-2"/>',calculator:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 10h1m6 0h1m-8 4h1m6 0h1m-8 4h1m6 0h1"/>',book:'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 1z"/>',arrow:'<path d="M4 12h16m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7m0-7-10 10M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',building:'<path d="M4 21V4h11v17m0-10h5v10M8 8h3M8 12h3M8 16h3M2 21h20"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18M7 14h3m4 0h3m-10 3h3"/>',check:'<path d="m5 12 4 4L19 6"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',chevron:'<path d="m9 5 7 7-7 7"/>',sliders:'<path d="M4 7h5m6 0h5M4 17h11m4 0h1"/><circle cx="12" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 15V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',phone:'<path d="M4 3h4l2 5-3 2c2 4 3 5 7 7l2-3 5 2v4c-10 3-20-7-17-17z"/>',wallet:'<path d="M20 8V4H4v16h16v-5M4 8h18v7h-7V8m3 4h.01"/>',leaf:'<path d="M20 3c1 15-8 20-14 14S5 2 20 3zM3 21l12-12"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 5 9 7 9-7"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 8M20 3v5h-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',compare:'<path d="M5 3v18M19 3v18M2 7h12m-4-4 4 4-4 4m12 6H10m4-4-4 4 4 4"/>'};
