const emptyStore=()=>({profiles:[],activeProfile:null,saved:[],records:{}});
function normalizeStore(x){
  if(!x||typeof x!=='object')throw Error('올바른 백업 파일이 아닙니다');
  const profiles=Array.isArray(x.profiles)?x.profiles.slice(0,10).filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string').map(p=>Object.fromEntries(['id','name','kind','region','city','industry','opened','employees','age','residence','revenue'].map(k=>[k,String(p[k]??'').slice(0,k==='name'?40:100)]))):[];
  const saved=[...new Set((Array.isArray(x.saved)?x.saved:[]).filter(id=>typeof id==='string'&&/^[\w-]{1,100}$/.test(id)))];
  const records={};if(x.records&&typeof x.records==='object')for(const [id,v] of Object.entries(x.records)){if(/^[\w-]{1,100}$/.test(id)&&v&&typeof v==='object')records[id]={status:['관심','준비중','신청완료','결과확인'].includes(v.status)?v.status:'관심',checks:Array.isArray(v.checks)?v.checks.filter(c=>typeof c==='string').slice(0,30):[],notes:String(v.notes??'').slice(0,2000)};}
  return {profiles,activeProfile:profiles.some(p=>p.id===x.activeProfile)?x.activeProfile:profiles[0]?.id||null,saved,records};
}
let state;try{state=normalizeStore(JSON.parse(localStorage.getItem(KEY)||JSON.stringify(emptyStore())));}catch{state=emptyStore();}
