function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('이 브라우저에서 저장할 수 없습니다. 백업으로 보관해 주세요.');}}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3500);}
function urlUpdate(){const u=new URL(location.href);u.search='';if(view!=='browse')u.searchParams.set('view',view);if(activeDetail)u.searchParams.set('notice',activeDetail);if(filters.region!=='전체')u.searchParams.set('region',filters.region);if(filters.type!=='전체')u.searchParams.set('type',filters.type);if(filters.purpose!=='전체')u.searchParams.set('purpose',filters.purpose);if(filters.category!=='전체')u.searchParams.set('category',filters.category);if(filters.subcategory!=='전체')u.searchParams.set('subcategory',filters.subcategory);if(filters.status!=='current')u.searchParams.set('status',filters.status);if(filters.query)u.searchParams.set('q',filters.query);if(filters.tag)u.searchParams.set('tag',filters.tag);history.replaceState({},'',u);}
const navItems=[['browse','search','지원사업 찾기'],['saved','bookmark','관심사업'],['prepare','checklist','신청 준비'],['calculator','calculator','자금 계산기'],['guide','book','이용 가이드']];
function navigate(next){page=1;view=next;filters.query='';filters.tag='';filters.type='전체';filters.purpose='전체';filters.category='전체';filters.subcategory='전체';filters.status='current';filters.matched=false;activeDetail=null;const u=new URL(location.href);u.search=next==='browse'?'':'?view='+next;history.pushState({},'',u);render();window.scrollTo({top:0,behavior:'instant'});}
function shell(content){return `
  <aside class="sidebar"><a class="brand" href="./"><img src="${e(brandIcon)}" alt="">지원한눈</a><p class="brand-caption">내 사업의 다음 기회를 찾다</p><p class="nav-label">MY SUPPORT</p><nav class="nav" aria-label="주 메뉴">${navItems.map(([id,i,t])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}${t}${id==='saved'?`<span class="count">${state.saved.length}</span>`:''}</button>`).join('')}</nav><div class="side-divider"></div><button class="side-link" data-action="calendar">${icon('calendar','sm')}마감일 모아보기</button><div class="sidebar-bottom"><div class="support-note"><div class="flex">${icon('shield','sm')}<strong>정부기관 공식 앱이 아닙니다</strong></div><p>지원한눈은 정부기관을 대표하거나 제휴·승인받지 않은 독립 서비스입니다.</p><p>${sourceLabel()}</p><button class="text-btn tiny" data-action="data-connect">공고 갱신 상태</button></div><button class="side-link" data-action="data-info">${icon('info','sm')}데이터·개인정보 안내</button><a class="side-link" href="./privacy.html">${icon('shield','sm')}개인정보처리방침</a></div></aside>
  <div class="site-main"><header class="topbar"><div class="breadcrumb">내 사업 지원정보 ${icon('chevron','sm')}<strong>${navItems.find(n=>n[0]===view)?.[2]}</strong></div><div class="flex"><span class="top-date">${koreanDate().replaceAll('-','.')} · 사업에 집중할 수 있도록</span><button class="avatar" data-action="profile" aria-label="내 사업 정보">${icon('user','sm')}</button></div></header><header class="mobile-header"><a class="brand" href="./"><img src="${e(brandIcon)}" alt="">지원한눈</a><button class="text-btn" data-action="calendar">${icon('calendar','sm')}마감일</button></header><main class="content" id="main" tabindex="-1">${content}<footer class="source-footer"><span>지원한눈 · ${sourceLabel()}<br>공고 조건과 접수 상태는 신청 기관에서 최종 확인하세요.</span><button data-action="data-info">데이터·개인정보 안내</button></footer></main></div>
  <nav class="bottom-nav" aria-label="모바일 메뉴">${navItems.filter(n=>n[0]!=='guide').map(([id,i,t])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}${id==='browse'?'찾기':id==='saved'?'관심사업':id==='prepare'?'신청 준비':'계산기'}</button>`).join('')}<button data-action="profile">${icon('user')}내 사업</button></nav><div id="compare-container">${tray()}</div>`;}
function tray(){return compared.length?`<div class="compare-tray"><div class="grow"><strong>${compared.length}개 사업 비교하기</strong><p>지원 내용·자부담·상환 조건을 한눈에</p></div><button class="text-btn" data-action="compare-clear">비우기</button><button class="btn" data-action="compare-open" ${compared.length<2?'disabled':''}>비교 ${icon('arrow','sm')}</button></div>`:'';}
function render(){const y=window.scrollY;app.innerHTML=shell(view==='browse'||view==='saved'?browse():view==='prepare'?prepare():view==='calculator'?calculator():guide());if(view==='calculator')calculate();if(['browse','saved'].includes(view))renderResults();window.scrollTo({top:y,behavior:'instant'});}
function profileStrip(){const p=profile();return `<section class="profile-strip" aria-label="내 사업 조건"><div class="flex"><div class="profile-icon">${icon('building')}</div><div><strong>${p?e(p.name):'내 사업에 맞는 지원을 찾고 싶다면?'}</strong>${p?`<div class="profile-chips"><span>${e(p.region)} ${e(p.city)}</span><span>${e(p.industry)}</span><span>${e(p.kind)}</span></div>`:'<p>지역·업종만 입력해도 관련 사업을 좁혀드려요.</p>'}</div></div><div class="flex">${state.profiles.length>1?`<label class="visually-hidden" for="profile-switch">사업 선택</label><select class="profile-switch" id="profile-switch">${state.profiles.map(p=>`<option value="${e(p.id)}" ${p.id===state.activeProfile?'selected':''}>${e(p.name)}</option>`).join('')}</select>`:''}<button class="btn ${p?'secondary':'soft'} small" data-action="profile">${p?'정보 수정':'사업 정보 입력'}${icon('chevron','sm')}</button></div></section>`;}
function browse(){const saved=view==='saved',p=profile(),open=programs.filter(p=>deadline(p).state!=='closed');return `${saved?`<div class="page-intro between"><div><p class="eyebrow">SAVED OPPORTUNITIES</p><h1>관심사업을 모아두세요</h1><p>좋은 기회는 저장하고, 준비는 하나씩 시작하세요.</p></div><button class="btn secondary small" data-action="calendar">${icon('calendar','sm')}마감일 보기</button></div>`:`<section class="hero"><div><p class="eyebrow">A LITTLE SUPPORT, A BIG NEXT STEP</p><h1>놓치던 지원,<br><span>내 사업에 딱 맞게.</span></h1><p>어려운 공고는 쉽게, 필요한 지원은 가깝게.<br>정책자금부터 지원금까지 한눈에 찾아보세요.</p><button class="btn primary" data-action="profile">${p?'내 사업 조건 수정':'30초 맞춤 찾기'}${icon('arrow','sm')}</button></div><div class="hero-art" aria-hidden="true"><div class="art-orbit"></div><div class="art-card back"><div class="art-square">${icon('wallet','sm')}</div><div class="art-label">정책자금</div><div class="art-value">더 나은 시작</div><div class="art-bar"></div></div><div class="art-card front"><div class="art-square">${icon('leaf','sm')}</div><div class="art-label">맞춤 지원사업</div><div class="art-value">다음 성장의 기회</div><div class="art-bar"></div><div class="art-bar short"></div></div><div class="art-check">${icon('check')}</div></div></section><section class="info-notice">${icon('shield')}<span><strong>정부기관 공식 앱이 아닙니다.</strong> 지원한눈은 공개된 지원사업 정보를 정리하고 공식 공고로 연결하는 독립 서비스입니다. <a href="https://www.bizinfo.go.kr/" target="_blank" rel="noopener noreferrer">공식 출처: 기업마당 ↗</a></span></section>`}${profileStrip()}${dataBanner()}${saved?'':metricCards()}
  <div class="section-heading between"><div><h2>${saved?'저장한 지원사업':'어떤 지원이 필요하세요?'}</h2><p>${saved?'저장한 사업의 상세 안내에서 신청 준비를 시작할 수 있어요.':'지역과 지원 유형을 선택하거나 필요한 내용을 검색하세요.'}</p></div><div class="source-badge"><span class="dot"></span>${sourceLabel()}</div></div>
  <section class="filters" id="search-filters" aria-label="지원사업 검색 및 필터">
    <div class="filter-panel-head"><div><h3>조회 조건</h3><p>필요한 조건을 선택하면 아래 공고가 갱신됩니다.</p></div><button class="filter-reset" data-action="reset-filters">${icon('refresh','sm')}조건 초기화</button></div>
    <div class="search-field"><label class="filter-label" for="query">검색어</label><form class="search-wrap" id="search-form">${icon('search')}<input id="query" type="search" placeholder="사업명, 키워드 검색 (예: 보험료, 스마트팜)" value="${e(filters.query)}" autocomplete="off"><button type="submit" class="btn primary small">조회</button></form></div>
    <div class="filter-line">
      <label class="filter-field" for="filter-region"><span>지역</span><select id="filter-region">${options(['전체',...regions],filters.region,{전체:'전국 지역'})}</select></label>
      <label class="filter-field" for="filter-type"><span>지원 유형</span><select id="filter-type">${options(['전체',...types],filters.type,{전체:'모든 지원 유형'})}</select></label>
      <label class="filter-field" for="filter-status"><span>접수 상태</span><select id="filter-status">${options(Object.keys(statusLabels),filters.status,statusLabels)}</select></label>
    </div>
    <div class="category-filter"><span class="filter-label">지원분야</span><div id="category-tabs" class="category-tabs" role="group" aria-label="공식 지원분야">${categoryTabs()}</div><label class="subcategory-label" for="filter-subcategory">세부 분야 <select id="filter-subcategory">${subcategoryOptions()}</select></label></div>
    <div class="purpose-filter"><span class="filter-label">지원 목적</span><div class="purpose-tabs" role="group" aria-label="지원 목적">${['전체',...purposes].map(t=>`<button class="chip ${filters.purpose===t?'active':''}" data-action="purpose" data-value="${e(t)}" aria-pressed="${filters.purpose===t}">${t==='전체'?'전체 목적':t}</button>`).join('')}</div></div>
    <div id="filter-summary" class="filter-summary" aria-live="polite">${filterSummary()}</div>
  </section>
  <div id="tag-filter" aria-live="polite">${tagFilter()}</div><div class="results-toolbar"><div id="result-count"></div><div class="flex">${p?`<label class="switch-label"><input type="checkbox" id="matched-only" ${filters.matched?'checked':''}>조건 불일치 제외</label>`:''}<label class="visually-hidden" for="sort">정렬</label><select class="sort" id="sort">${options(['latest','deadline','amount',...(p?['match']:[])],filters.sort,{latest:'최근 공고순',deadline:'마감 임박순',amount:'확인된 한도순',match:'관련 조건순'})}</select></div></div><div id="list" class="cards"></div><div id="pagination" class="pagination" aria-label="공고 페이지"></div><p class="pagination-note">수집한 공고 전체에서 검색합니다. 제공처별 중복 공고는 제목·마감일 기준으로 통합합니다. ‘마감 제외’에는 기간 미확인 공고도 포함됩니다. 전국 모든 기관·과거 전체 공고 건수가 아닙니다. <a class="green" href="https://www.bizinfo.go.kr/" target="_blank" rel="noopener noreferrer">기업마당에서 전체 공고 확인 ${icon('external','sm')}</a></p>`;}
function metricActive(key){const preset=metricFilters(key);return Object.keys(preset).filter(k=>k!=='sort').every(k=>(filters[k]??preset[k])===preset[k]);}
function metricCards(){
  return `<section class="metrics" aria-label="확인된 공고 현황">${[['all','layers','metric-count',dataState.count,dataState.catalog?'중복 제거 통합 공고':dataState.mode==='live'?'현재 API 수집 공고':'초기 확인 공고'],['urgent','clock','metric-urgent',metrics.urgent,metricLabels.urgent],['financial','wallet','metric-financial',metrics.financial,metricLabels.financial]].map(([key,i,id,count,label])=>`<button type="button" class="metric metric-action ${metricActive(key)?'active':''}" data-action="metric" data-value="${key}" aria-label="${e(metricLabels[key])} 공고 조회" aria-describedby="${id}" aria-pressed="${metricActive(key)}"><div class="metric-head"><div class="metric-icon">${icon(i)}</div><span class="label">${e(label)}</span></div><div class="number" id="${id}">${count.toLocaleString('ko-KR')}<small>건</small></div><span class="metric-link">${metricActive(key)?'조회 중인 조건':'공고 보기'} ${icon('arrow','sm')}</span></button>`).join('')}</section>`;
}
function filterSummary(){return `<strong>적용된 조건</strong><div class="filter-summary-chips">${filterChips(filters).map(c=>`<span class="filter-summary-chip ${c.key==='status'&&filters.status==='urgent'?'urgent':''}"><span>${e(c.label)}</span>${e(c.value)}</span>`).join('')}</div>`;}
function updateFilterState(){
  const summary=document.getElementById('filter-summary');if(summary)summary.innerHTML=filterSummary();
  for(const [id,defaultValue] of [['filter-region','전체'],['filter-type','전체'],['filter-status','current']]){const control=document.getElementById(id);control?.closest('.filter-field')?.classList.toggle('selected',control.value!==defaultValue);}
  const subcategory=document.getElementById('filter-subcategory');subcategory?.closest('.subcategory-label')?.classList.toggle('selected',filters.subcategory!=='전체');
  document.querySelectorAll('[data-action="metric"]').forEach(b=>{const active=metricActive(b.dataset.value);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));b.querySelector('.metric-link').innerHTML=`${active?'조회 중인 조건':'공고 보기'} ${icon('arrow','sm')}`;});
}
function options(values,selected,labels={}){return values.map(v=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(labels[v]||v)}</option>`).join('');}
function resultList(){return filterPrograms(programs,{...filters,view},profile(),state.saved);}
function categoryTabs(){return ['전체',...categories].map(t=>`<button class="chip ${filters.category===t?'active':''}" data-action="category" data-value="${e(t)}" aria-pressed="${filters.category===t}">${t==='전체'?'전체 분야':e(t)}${facetState.categoryCounts[t]!==undefined?`<span class="facet-count">${facetState.categoryCounts[t].toLocaleString('ko-KR')}</span>`:''}</button>`).join('');}
function subcategoryOptions(){const list=[...facetState.subcategories];if(filters.subcategory!=='전체'&&!list.some(x=>x.name===filters.subcategory))list.unshift({name:filters.subcategory,count:0});return `<option value="전체">모든 세부 분야</option>`+list.map(x=>`<option value="${e(x.name)}" ${filters.subcategory===x.name?'selected':''}>${e(x.name)} (${x.count})</option>`).join('');}
function tagFilter(total){return filters.tag?`<div class="active-tag-filter"><div><strong>#${e(filters.tag)} 태그로 조회</strong><span class="tag-result-status">${total===undefined?'조회 중…':`${total.toLocaleString('ko-KR')}건`}</span></div><button class="text-btn" data-action="clear-tag">태그 해제 ${icon('x','sm')}</button></div>`:'';}
function syncSearchControls(){
  for(const [id,key] of [['query','query'],['filter-region','region'],['filter-type','type'],['filter-status','status'],['sort','sort']]){const control=document.getElementById(id);if(control)control.value=filters[key];}
  const matched=document.getElementById('matched-only');if(matched)matched.checked=filters.matched;
  document.querySelector('#category-tabs').innerHTML=categoryTabs();document.querySelector('#filter-subcategory').innerHTML=subcategoryOptions();
  document.querySelectorAll('[data-action="purpose"]').forEach(c=>{c.classList.toggle('active',c.dataset.value===filters.purpose);c.setAttribute('aria-pressed',String(c.dataset.value===filters.purpose));});
}
function drawResults(result){
  if(!['browse','saved'].includes(view))return;const scrollY=window.scrollY;for(const [id,key] of [['metric-urgent','urgent'],['metric-financial','financial']]){const el=document.getElementById(id);if(el&&result[key]!==undefined)el.innerHTML=result[key].toLocaleString('ko-KR')+'<small>건</small>';}page=result.page;mergePrograms(result.programs);if(result.categoryCounts){facetState={categoryCounts:result.categoryCounts,subcategories:result.subcategories};document.querySelector('#category-tabs').innerHTML=categoryTabs();document.querySelector('#filter-subcategory').innerHTML=subcategoryOptions();}
  document.querySelector('#result-count').innerHTML=`<span class="result-count">검색 결과 <strong>${result.total.toLocaleString('ko-KR')}</strong>건${filters.matched?' · 입력 조건 기준':''}</span>${result.withinPeriod!==undefined?`<p class="result-coverage">전체 수집본 기준 · 진행중·기간 내 ${result.withinPeriod.toLocaleString('ko-KR')}건 · 기간 미확인 ${result.unknownPeriod.toLocaleString('ko-KR')}건</p>`:''}`;
  document.querySelector('#list').setAttribute('aria-busy','false');
  document.querySelector('#list').innerHTML=result.programs.length?result.programs.map(card).join(''):`<div class="empty">${icon(view==='saved'?'bookmark':'search')}<h3>${view==='saved'&&state.saved.length===0?'관심사업을 아직 저장하지 않았어요':'조건에 맞는 공고가 없어요'}</h3><p>전체 분야·모든 세부 분야를 선택하거나 다른 검색 조건을 넓혀보세요.</p><button class="btn soft" data-action="reset-filters">검색 조건 초기화</button></div>`;
  document.querySelector('#tag-filter').innerHTML=tagFilter(result.total);
  document.querySelector('#pagination').innerHTML=result.pages>1?`<button class="btn secondary small" data-action="page" data-page="${page-1}" ${page===1?'disabled':''}>이전</button><span>${page} / ${result.pages} 페이지 · ${result.pageSize}건씩</span><button class="btn secondary small" data-action="page" data-page="${page+1}" ${page===result.pages?'disabled':''}>다음</button>`:'';
  const count=document.querySelector('#metric-count');if(count&&result.sourceCount){dataState.count=result.sourceCount;count.innerHTML=result.sourceCount.toLocaleString('ko-KR')+'<small>건</small>';}
  updateFilterState();window.scrollTo({top:scrollY,behavior:'instant'});
  if(pendingMetricFeedback){if(metricActive(pendingMetricFeedback))toast(`${metricLabels[pendingMetricFeedback]} ${result.total.toLocaleString('ko-KR')}건을 조회했습니다.`);pendingMetricFeedback=null;}
  if(pendingTagFeedback===filters.tag&&filters.tag){toast(`#${filters.tag} 공고 ${result.total.toLocaleString('ko-KR')}건을 조회했습니다.`);pendingTagFeedback=null;}
}
function renderResults(reset=true){
  if(!['browse','saved'].includes(view))return;if(reset)page=1;updateFilterState();
  clearTimeout(searchTimer);searchController?.abort();const serial=++searchSerial;
  if(!serverReady||dataState.mode!=='live'||view==='saved'){drawResults({...pageSlice(resultList(),page),...categoryFacets(programs,{...filters,view},profile(),state.saved)});return;}
  document.querySelector('#result-count').textContent='전체 공고 검색 중…';
  const scrollY=window.scrollY;document.querySelector('#tag-filter').innerHTML=tagFilter();window.scrollTo({top:scrollY,behavior:'instant'});
  document.querySelector('#list').setAttribute('aria-busy','true');
  searchTimer=setTimeout(async()=>{searchController=new AbortController();
    try{const p=profile();const criteria=filters.matched||filters.sort==='match'?p&&Object.fromEntries(['kind','region','city','industry','opened','employees','age','residence'].map(k=>[k,p[k]])):null;
      const result=await api('/api/programs',{filters:{...filters,view:'browse'},profile:criteria,page,pageSize:12},searchController.signal);
      if(serial!==searchSerial)return;metrics=result;drawResults(result);
    }catch(err){if(err.name==='AbortError'||serial!==searchSerial)return;document.querySelector('#list').setAttribute('aria-busy','false');document.querySelector('#result-count').textContent='검색 실패';pendingMetricFeedback=null;if(filters.tag)document.querySelector('#tag-filter .tag-result-status').textContent='조회 실패 · 다시 검색해 주세요';document.querySelector('#list').innerHTML=`<div class="empty"><h3>공고를 불러오지 못했어요</h3><p>${e(err.message)}</p><button class="btn soft" data-action="retry-search">다시 검색</button></div>`;document.querySelector('#pagination').innerHTML='';}
  },250);
}

function typeClass(t){return t==='정책융자'?'loan':t==='이자지원'?'interest':t==='서비스·현물'?'service':'';}
function card(p){const d=deadline(p),m=match(p,profile()),saved=state.saved.includes(p.id);return `<article class="program-card ${compared.includes(p.id)?'compared':''}"><div class="card-top"><div class="badges"><span class="badge category">${e(categoryLabel(p))}</span><span class="badge ${typeClass(p.type)}">${e(p.type)}</span><span class="badge region">${e(p.city||p.region)}</span></div><span class="deadline ${d.state}">${d.label}</span></div><button class="card-title" data-action="detail" data-id="${p.id}"><h3>${e(p.title)}</h3></button><div class="agency">${e(p.agency)}</div>${p.subcategory?`<p class="card-subcategory">${e(p.subcategory)}</p>`:''}<div class="benefit ${p.benefit.length>14?'long':''}">${e(p.benefit)}</div><p class="card-summary">${e(p.summary)}</p><div class="card-tags">${renderTagLinks(p,location.href,filters.tag)}</div>${profile()?`<button class="match-line ${m.state}" data-action="detail" data-id="${p.id}">${icon(m.state==='mismatch'?'info':'check','sm')}${e(m.label)}${icon('chevron','sm')}</button>`:''}<div class="card-footer"><label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${compared.includes(p.id)?'checked':''}>비교 담기</label><div class="card-actions"><button class="icon-btn ${saved?'selected':''}" data-action="save" data-id="${p.id}" aria-label="${e(p.title)} ${saved?'관심 저장 해제':'관심 저장'}" aria-pressed="${saved}">${icon('bookmark','sm')}</button><button class="text-btn" data-action="detail" data-id="${p.id}">신청 안내 ${icon('arrow','sm')}</button></div></div><div class="period">${period(p)}${p.firstCome?' · 선착순 조기 마감 가능':''}</div></article>`;}
function period(p){if(p.imported)return e(p.periodText);return p.end?`${p.start?.replaceAll('-','.')||''} – ${p.end.replaceAll('-','.')}`:'예산 소진 시까지 · 현재 접수 여부 확인 필요';}
function baseChecks(p){return [...p.documents.map((title,i)=>({id:'doc-'+i,title,official:true})),{id:'original',title:'최신 원문·첨부 서류·접수 마감 시각 확인',url:p.sourceUrl},{id:'eligibility',title:'제외업종·중복지원·세부 자격 조건 확인'},{id:'proof',title:'사업자·매출·고용 등 요구 증빙 목록 확인'}];}
function prepare(){const list=state.saved.map(id=>programs.find(p=>p.id===id)).filter(Boolean);return `<div class="page-intro between"><div><p class="eyebrow">ONE STEP AT A TIME</p><h1>신청 준비, 하나씩 차근차근</h1><p>서류 체크와 신청 상태를 이 브라우저에 저장합니다.</p></div><button class="btn secondary small" data-action="calendar">${icon('calendar','sm')}마감일 모아보기</button></div><div class="info-notice">${icon('info')}<span>공고에 확인된 서식과 일반 준비 항목을 구분했어요. 제출 서류의 최종 목록은 반드시 최신 원문을 확인하세요.</span></div>${list.length?list.map(p=>{const r=record(p.id),checks=baseChecks(p),completed=checks.filter(c=>r.checks.includes(c.id)).length;return `<section class="panel prep-card" data-program="${p.id}"><div class="between"><div><div class="badges"><span class="badge ${typeClass(p.type)}">${p.type}</span><span class="deadline ${deadline(p).state}">${deadline(p).label}</span></div><h3 style="margin-top:9px;margin-bottom:0">${e(p.title)}</h3></div><label><span class="visually-hidden">${e(p.title)} 신청 상태</span><select class="prep-status" data-record-status="${p.id}">${options(['관심','준비중','신청완료','결과확인'],r.status)}</select></label></div><div class="progress-track"><div style="width:${Math.round(completed/checks.length*100)}%"></div></div><div class="between tiny muted"><span>준비 체크 ${completed} / ${checks.length}</span><span>${Math.round(completed/checks.length*100)}%</span></div>${p.documents.length?'<p class="sub-label">공고에서 확인한 신청 서식</p>':''}<div class="checklist">${checks.map((c,i)=>`${!c.official&&i===p.documents.length?'<p class="sub-label">일반 준비 항목 · 제출 서류 확정 목록이 아닙니다</p>':''}<label class="check-row"><input type="checkbox" data-check="${e(c.id)}" data-id="${p.id}" ${r.checks.includes(c.id)?'checked':''}><span>${e(c.title)}</span>${c.url?`<a href="${e(c.url)}" target="_blank" rel="noopener noreferrer">원문 ${icon('external','sm')}</a>`:''}</label>`).join('')}</div><label class="field"><span class="field-label">준비 메모</span><textarea class="notes" data-notes="${p.id}" maxlength="2000" placeholder="담당자에게 확인할 내용이나 준비할 자료를 적어두세요.">${e(r.notes)}</textarea></label><div class="between spaced"><span class="muted tiny">자동 저장 · 이 브라우저에서만 보관</span><button class="text-btn" data-action="detail" data-id="${p.id}">신청 안내 ${icon('arrow','sm')}</button></div></section>`;}).join(''):`<div class="empty">${icon('checklist')}<h3>준비할 지원사업을 먼저 골라주세요</h3><p>관심 저장한 사업의 체크리스트가 여기에 표시됩니다.</p><button class="btn primary" data-action="find">지원사업 찾아보기 ${icon('arrow','sm')}</button></div>`}`;}
function calculator(){return `<div class="page-intro"><p class="eyebrow">KNOW YOUR NUMBERS</p><h1>자금 계획을 미리 세워보세요</h1><p>대출 상환액과 지원사업의 자부담을 직접 계산해 보세요.</p></div><div class="calculator-grid"><section class="panel"><div class="panel-icon">${icon('calculator')}</div><h3>대출 상환 계산</h3><p>금액과 금리를 입력해 예상 부담을 확인하세요.</p><form id="loan-form" class="spaced"><div class="form-grid"><label class="field wide"><span class="field-label">대출 금액 (원)</span><input id="loan-amount" type="number" min="1" max="100000000000" step="1" value="50000000" required></label><label class="field"><span class="field-label">연 금리 (%)</span><input id="loan-rate" type="number" min="0" max="100" step="0.01" value="4" required></label><label class="field"><span class="field-label">상환 기간 (개월)</span><input id="loan-months" type="number" min="1" max="600" step="1" value="60" required></label><label class="field wide"><span class="field-label">상환 방식</span><select id="loan-method">${options(['equalPayment','equalPrincipal'],'equalPayment',{equalPayment:'원리금균등 · 매월 같은 원금+이자',equalPrincipal:'원금균등 · 원금은 같고 이자는 감소'})}</select></label></div><button class="btn primary spaced" type="submit">상환액 계산 ${icon('arrow','sm')}</button></form><div id="loan-result" aria-live="polite"></div><p class="muted tiny spaced">거치기간·보증료·이자지원·중도상환수수료는 제외한 예시입니다. 실제 적용 금리와 약정에 따라 달라집니다.</p></section><section class="panel"><div class="panel-icon">${icon('wallet')}</div><h3>지원금·자부담 계산</h3><p>지원 비율과 한도를 함께 반영합니다.</p><form id="subsidy-form" class="spaced"><div class="form-grid"><label class="field wide"><span class="field-label">총 사업비 (원)</span><input id="subsidy-cost" type="number" min="0" max="100000000000" step="1" value="10000000" required></label><label class="field"><span class="field-label">지원 비율 (%)</span><input id="subsidy-ratio" type="number" min="0" max="100" step="0.01" value="60" required></label><label class="field"><span class="field-label">지원 한도 (원)</span><input id="subsidy-cap" type="number" min="0" max="100000000000" step="1" value="5000000" required></label></div><button class="btn primary spaced" type="submit">자부담 계산 ${icon('arrow','sm')}</button></form><div id="subsidy-result" aria-live="polite"></div><div class="info-notice">${icon('info')}<span>초기 값은 청양군 음식점 시설개선 공고의 비율(60%)과 한도(500만원)를 참고한 예시입니다. 자격과 선정 여부를 의미하지 않습니다.</span></div><p class="muted tiny">부가세·지원 제외 항목·사업비 인정 범위는 별도로 확인하세요.</p></section></div>`;}
function calculate(which){if(!which||which==='loan'){const f=document.querySelector('#loan-form');if(f.checkValidity()){try{const r=loanEstimate(document.querySelector('#loan-amount').value,document.querySelector('#loan-rate').value,document.querySelector('#loan-months').value,document.querySelector('#loan-method').value);document.querySelector('#loan-result').innerHTML=`<div class="calc-result"><span class="muted tiny">${document.querySelector('#loan-method').value==='equalPayment'?'예상 월 상환액':'예상 첫 달 상환액'}</span><div class="big">${money(r.first)}</div><div class="calc-row"><span>마지막 달 상환액</span><strong>${money(r.last)}</strong></div><div class="calc-row"><span>총 이자</span><strong>${money(r.interest)}</strong></div><div class="calc-row"><span>총 상환액</span><strong>${money(r.total)}</strong></div></div>`;}catch(err){toast(err.message);}}else if(which)f.reportValidity();}if(!which||which==='subsidy'){const f=document.querySelector('#subsidy-form');if(f.checkValidity()){const r=subsidyEstimate(document.querySelector('#subsidy-cost').value,document.querySelector('#subsidy-ratio').value/100,document.querySelector('#subsidy-cap').value);document.querySelector('#subsidy-result').innerHTML=`<div class="calc-result"><span class="muted tiny">예상 자부담</span><div class="big">${money(r.own)}</div><div class="calc-row"><span>예상 지원금</span><strong>${money(r.support)}</strong></div><div class="calc-row"><span>총 사업비</span><strong>${money(Number(document.querySelector('#subsidy-cost').value))}</strong></div></div>`;}else if(which)f.reportValidity();}}
function guide(){return `<div class="page-intro"><p class="eyebrow">A CLEARER WAY TO APPLY</p><h1>지원사업이 처음이어도 괜찮아요</h1><p>돈의 성격부터 신청 순서까지, 필요한 것만 쉽게 정리했어요.</p></div><div class="panels">${[['wallet','지원금·보조금','공고 조건에 따라 비용을 지원해요. 사용처, 자부담, 정산 의무를 확인하세요.'],['calculator','정책융자','원금과 이자를 갚는 대출이에요. 한도보다 금리·거치·상환 조건을 함께 보세요.'],['leaf','이자지원','대출 이자의 일부를 지원해요. 대출 원금을 대신 갚아주는 지원은 아니에요.'],['building','서비스·현물','촬영·컨설팅·장비·데이터 등을 지원해요. 현금이 입금되는 사업과 구분하세요.']].map(([i,t,c])=>`<section class="panel"><div class="panel-icon">${icon(i)}</div><h3>${t}</h3><p>${c}</p></section>`).join('')}</div><h2 class="spaced" style="margin-bottom:15px">신청은 이렇게 진행하세요</h2><section class="panel"><div class="checklist">${['사업 정보를 입력하고 지역·업종이 관련된 공고 찾기','상세 안내에서 추가 확인 조건과 최신 원문 읽기','관심 저장 후 신청 준비 체크리스트 작성하기','공식 접수처에서 신청하고 접수 완료 여부 확인하기'].map((t,i)=>`<div class="flex"><span class="badge">0${i+1}</span><span class="tiny">${t}</span></div>`).join('')}</div></section><h2 class="spaced" style="margin-bottom:15px">공식 창구 바로가기</h2><section class="panel">${[['기업마당','중소기업·소상공인 지원사업 공고','https://www.bizinfo.go.kr/'],['소상공인24','소상공인 지원사업 안내와 접수','https://www.sbiz24.kr/'],['K-Startup','창업지원사업 공식 안내','https://www.k-startup.go.kr/'],['홈택스','사업자·세금 관련 증빙 확인','https://www.hometax.go.kr/'],['정부24','공공 증명서·민원 서비스','https://www.gov.kr/']].map(([t,c,u])=>`<a class="portal-link" href="${u}" target="_blank" rel="noopener noreferrer"><div><strong>${t}</strong><small>${c}</small></div>${icon('external','sm')}</a>`).join('')}</section><h2 class="spaced" style="margin-bottom:15px">자주 묻는 질문</h2>${[['조건이 일치하면 반드시 선정되나요?','지역·업종 등 입력한 조건을 대조한 결과입니다. 제외업종, 매출 산정 기준, 중복지원, 예산 잔여와 기관 심사는 별도로 확인해야 합니다. 승인 확률을 계산하거나 선정 여부를 보장하지 않습니다.'],['확인된 한도를 합산해도 되나요?','융자는 대출이고 지원금은 비용 지원입니다. 중복 수혜 제한과 심사 조건도 달라 한도를 받을 수 있는 총액으로 합산하면 안 됩니다.'],['새 공고가 자동으로 추가되나요?','매일 한국시간 06:17에 공고를 수집해 갱신합니다. 화면에는 마지막 성공 시점의 자료를 표시합니다. 공고 갱신 상태에서 수집 시각과 제공처별 건수를 확인할 수 있으며, 갱신 실패 시 이전 자료를 유지합니다.'],['알림은 어떻게 받을 수 있나요?','관심사업 마감일을 캘린더 파일로 저장할 수 있습니다. 캘린더에 가져오면 마감 3일 전 알림을 요청합니다. 실제 알림은 사용하시는 캘린더 설정에 따릅니다. 앱 자체의 백그라운드 푸시 알림은 제공하지 않습니다.'],['사업 정보는 어디에 저장되나요?','프로필, 관심사업, 체크리스트와 메모는 현재 브라우저에 저장됩니다. 전체 공고에서 조건 불일치 제외·관련 조건순 검색을 할 때 필요한 조건만 서버에 전송하여 비교하며 서버에 저장하지 않습니다. 다른 기기로 옮길 때는 백업 파일을 내보내고 가져오세요. 주민등록번호·계좌번호·사업자번호는 입력받지 않습니다.']].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}<section class="panel spaced"><h3>내 데이터 관리</h3><p>기기를 바꾸기 전에 프로필과 신청 준비 기록을 백업해 두세요.</p><div class="store-actions"><button class="btn secondary small" data-action="backup">${icon('download','sm')}백업 내보내기</button><button class="btn secondary small" data-action="import">${icon('upload','sm')}백업 가져오기</button><button class="btn secondary small" data-action="install">${icon('plus','sm')}홈 화면에 추가</button><button class="text-btn tiny" data-action="clear-data">저장 데이터 삭제</button></div><input class="visually-hidden" id="import-file" type="file" accept="application/json,.json"></section>`;}
function showDialog(title,body,actions='',cls=''){dialogLayers.closeViewer(false);dialog.className=cls;dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button class="icon-btn" data-action="close" aria-label="닫기">${icon('x','sm')}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!dialog.open)dialog.showModal();}
function showViewer(title,body,actions='',opener){
  const markup=`<div class="dialog-head"><h2 id="viewer-title">${e(title)}</h2><button class="icon-btn" data-action="close-viewer" aria-label="뷰어 닫고 상세로 돌아가기">${icon('x','sm')}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;
  dialogLayers.openViewer(markup,'document-dialog',opener);
}
async function details(id){id=noticeAliases.get(id)||id;let p=programs.find(p=>p.id===id);if(!p)return;activeDetail=id;urlUpdate();
if(p.detailPending){showDialog('지원사업 상세 안내',`<p>${e(p.title)}</p><div class="pdf-status" role="status">공고 상세를 불러오고 있습니다…</div>`,`<a class="btn primary" href="${e(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">제공처 공고 보기 ↗</a>`);try{const result=await api('/api/notice-detail',{id});if(activeDetail!==id||!dialog.open)return;p=result.program;mergePrograms([p]);}catch(error){if(activeDetail!==id||!dialog.open)return;showDialog('공고 상세 연결 안내',`<p>${e(error.message)}</p>`,`<a class="btn primary" href="${e(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">제공처 공고 보기 ↗</a>`);return;}}
const d=deadline(p),m=match(p,profile());showDialog('지원사업 상세 안내',`${renderClassification(p)}<div class="detail-tags card-tags">${renderTagLinks(p,location.href,filters.tag)}</div><div class="badges"><span class="badge ${typeClass(p.type)}">${p.type}</span><span class="badge region">${e(p.city||p.region)}</span><span class="deadline ${d.state}">${d.label}</span></div><h1>${e(p.fullTitle||p.title)}</h1><div class="benefit">${e(p.benefit)}</div>${renderNoticeLinks(p)}${renderOverview(p)}<div class="detail-grid"><div class="detail-cell wide"><small>지원 대상</small><strong>${e(p.target)}</strong></div><div class="detail-cell"><small>접수 기간 · 공고 기준</small><strong>${period(p)}</strong></div><div class="detail-cell"><small>소관부처·지자체</small><strong>${e(p.supervisingAgency||p.agency)}</strong></div><div class="detail-cell"><small>사업 수행기관</small><strong>${e(p.executingAgency||p.agency)}</strong></div><div class="detail-cell"><small>자부담·비용</small><strong>${e(p.cost)}</strong></div><div class="detail-cell"><small>상환·지원 성격</small><strong>${e(p.repayment)}</strong></div></div><div class="condition-heading"><h3>내 조건과 맞는지 확인하세요</h3><button class="text-btn" data-action="profile">${profile()?'사업 정보 수정':'사업 정보 입력'} ${icon('chevron','sm')}</button></div>${profile()?`<div class="conditions">${m.pass.map(t=>`<div class="condition">${icon('check')}<span>${e(t)}</span></div>`).join('')}${m.fail.map(t=>`<div class="condition fail">${icon('x')}<span>${e(t)}</span></div>`).join('')}</div>`:'<p>사업 정보를 입력하면 지역·업종·사업자 유형 등을 대조해 드려요.</p>'}<h3>추가로 확인할 조건</h3><div class="conditions">${(profile()?m.unknown:p.requirements).map(t=>`<div class="condition unknown">${icon('info')}<span>${e(t)}</span></div>`).join('')}</div><div class="info-notice">${icon('shield')}<span>입력 조건 대조는 선정 여부나 승인 확률을 뜻하지 않습니다. 세부 요건·제외업종·중복 수혜·예산 잔여는 공식 기관에 확인하세요.</span></div><h3>신청 방법</h3><p>${e(p.method)}</p>${p.application?`<a class="btn secondary small spaced" href="${e(p.application)}" target="_blank" rel="noopener noreferrer">공식 접수처 홈페이지 ${icon('external','sm')}</a>`:''}<h3>신청 서류 준비</h3>${p.documents.length?`<p>공고에서 확인한 서식: ${p.documents.map(e).join(', ')}.</p>`:'<p>첨부파일에 있는 제출 서류 목록을 확인해 주세요.</p>'}<p class="muted tiny" style="margin-top:6px">완전한 제출 서류 목록은 원문·첨부파일에서 확인합니다. 관심 저장하면 준비 체크리스트를 사용할 수 있어요.</p>${renderAttachments(p)}<h3>문의처</h3><p>${e(p.contact)}</p><div class="flex" style="margin-top:10px">${p.phone?`<a class="btn secondary small" href="tel:${p.phone}">${icon('phone','sm')}전화 문의</a>`:''}${p.email?`<a class="btn secondary small" href="mailto:${e(p.email)}">${icon('mail','sm')}이메일 작성</a>`:''}${p.end?`<button class="btn secondary small" data-action="ics" data-id="${p.id}">${icon('calendar','sm')}마감일 저장</button>`:''}</div><p class="muted tiny spaced">출처: ${p.sourceProvider==='npay'?'Npay 공개 공고 · 원문 제공기관 확인':'기업마당 공식 공고'} · 확인 ${p.checkedAt.replaceAll('-','.')}<br>접수 마감 시각·조기 마감·변경 공고는 최신 원문 확인</p>`,`<button class="btn secondary" data-action="share" data-id="${p.id}">${icon('external','sm')}공유</button><button class="btn soft" data-action="start-prepare" data-id="${p.id}">${icon('checklist','sm')}신청 준비</button><a class="btn primary" href="${e(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${p.sourceProvider==='npay'?'공고 원문 보기':'기업마당 공고 보기'} ${icon('external','sm')}</a>`);}
function profileDialog(isNew=false){const p=isNew?null:profile();activeDetail=null;urlUpdate();showDialog(p?'내 사업 정보 수정':'내 사업 정보 입력',`<p class="dialog-subtitle">입력한 조건으로 관련 사업을 찾아드려요. 이름·번호 인증 없이 시작하세요.</p><p class="profile-privacy">${icon('shield','sm')} 프로필은 이 브라우저에 저장합니다. 맞춤 검색 시 필요한 조건을 서버에서 일시 비교합니다. 대표자 연령과 개업일은 선택 입력입니다.</p><form id="profile-form"><input type="hidden" name="id" value="${e(p?.id||'')}"><div class="form-grid"><label class="field wide"><span class="field-label">사업 별명 *</span><input name="name" value="${e(p?.name||'')}" placeholder="예: 우리 가게, 창업 프로젝트" maxlength="40" required></label><label class="field"><span class="field-label">사업자 유형 *</span><select name="kind" required>${options(['소상공인','중소기업','중견기업','농업경영체','예비창업자'],p?.kind||'소상공인')}</select><small>공고상 기업 규모 요건은 따로 확인해 주세요.</small></label><label class="field"><span class="field-label">사업장 지역 *</span><select name="region" required><option value="">선택해 주세요</option>${options(regions,p?.region)}</select></label><label class="field"><span class="field-label">시·군·구 (선택)</span><input name="city" value="${e(p?.city||'')}" placeholder="예: 서산시, 청양군" maxlength="30"><small>입력한 명칭으로 세부 지역을 비교합니다.</small></label><label class="field"><span class="field-label">업종 *</span><select name="industry" required><option value="">선택해 주세요</option>${options(industries,p?.industry)}</select></label><label class="field"><span class="field-label">개업일 (선택)</span><input name="opened" type="date" max="${koreanDate()}" value="${e(p?.opened||'')}"></label><label class="field"><span class="field-label">상시 근로자 수 (선택)</span><input name="employees" type="number" min="0" max="100000" step="1" placeholder="대표자 제외" value="${e(p?.employees||'')}"></label><label class="field"><span class="field-label">대표자 만 나이 (선택)</span><input name="age" type="number" min="18" max="120" step="1" placeholder="청년사업 조건 확인용" value="${e(p?.age||'')}"></label><label class="field"><span class="field-label">주민등록상 거주 지역 (선택)</span><select name="residence"><option value="">선택하지 않음</option>${options(regions,p?.residence)}</select></label><label class="field wide"><span class="field-label">전년도 매출 구간 (선택)</span><select name="revenue">${options(['','1억원 미만','1억~3억원','3억~10억원','10억원 이상'],p?.revenue||'',{'':'선택하지 않음'})}</select><small>내 준비 기록용입니다. 현재 공고의 매출 자격을 자동 판정하지 않습니다.</small></label></div><div class="info-notice">${icon('info')}<span>업종과 사업자 유형은 검색을 좁히는 기준입니다. 농업경영체 등록만으로 소상공인 지원 자격이 인정되지는 않습니다.</span></div><div class="between">${p?`<button class="text-btn tiny" type="button" data-action="delete-profile" data-id="${e(p.id)}">이 사업 정보 삭제</button>`:'<span class="muted tiny">* 필수 입력</span>'}<button class="btn primary" type="submit">저장하고 맞춤 찾기 ${icon('arrow','sm')}</button></div></form>${p&&state.profiles.length<10?`<button class="text-btn tiny spaced" data-action="new-profile">${icon('plus','sm')}다른 사업 추가하기</button>`:''}`);}
function compareDialog(){const list=compared.map(id=>programs.find(p=>p.id===id));if(list.length<2)return;const rows=[['지원사업',p=>`<strong>${e(p.title)}</strong>`],['지원 유형',p=>`<span class="badge ${typeClass(p.type)}">${p.type}</span>`],['지역',p=>e(p.city||p.region)],['지원 내용',p=>e(p.benefit)],['자부담·비용',p=>e(p.cost)],['상환·지원 성격',p=>e(p.repayment)],['접수 기간',p=>period(p)],['입력 조건',p=>e(match(p,profile()).label)],['신청 방법',p=>e(p.method)],['원문',p=>`<a class="text-btn" href="${e(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">공식 공고 ${icon('external','sm')}</a>`]];showDialog('지원사업 비교',`<p class="dialog-subtitle">금액의 크기보다 지원 성격과 실제 부담을 함께 확인하세요.</p><div class="compare-scroll"><table class="compare-table"><caption class="visually-hidden">선택한 지원사업의 지원 내용과 상환 조건 비교</caption><thead><tr><th scope="col">비교 항목</th>${list.map(p=>`<td><strong>${e(p.title)}</strong></td>`).join('')}</tr></thead><tbody>${rows.slice(1).map(([t,fn])=>`<tr><th scope="row">${t}</th>${list.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="info-notice">${icon('info')}<span>대출 한도와 지원금은 합산하지 않습니다. 중복 지원 가능 여부는 각 기관에 확인하세요.</span></div>`,`<button class="btn secondary" data-action="compare-export">${icon('download','sm')}비교표 CSV 저장</button><button class="btn primary" data-action="close">확인</button>`,'compare-dialog');}
function calendarDialog(){const list=state.saved.map(id=>programs.find(p=>p.id===id)).filter(p=>p?.end).sort((a,b)=>a.end.localeCompare(b.end));showDialog('관심사업 마감일',`<p class="dialog-subtitle">마감일을 캘린더에 추가하면 3일 전 알림을 요청할 수 있어요. 접수 시간과 조기 마감은 원문을 확인하세요.</p><div class="calendar-list">${list.length?list.map(p=>`<div class="portal-link"><div><strong>${e(p.title)}</strong><small>${p.end.replaceAll('-','.')} · ${deadline(p).label}</small></div><button class="btn soft small" data-action="ics" data-id="${p.id}">${icon('download','sm')}저장</button></div>`).join(''):'<div class="empty"><h3>마감일이 있는 관심사업이 없어요</h3><p>사업을 관심 저장하면 마감일을 모아볼 수 있습니다.</p></div>'}</div><p class="muted tiny spaced">예산 소진 시 종료되는 공고는 확정 마감일이 없어 여기에 표시하지 않습니다. 앱 자체 푸시 알림은 제공하지 않습니다.</p>`);}
function dataDialog(){showDialog('데이터·개인정보 안내',`<h3 style="margin-top:0">서비스 성격과 공식 출처</h3><p><strong>지원한눈은 정부기관의 공식 앱이 아니며 정부·지자체·공공기관을 대표하거나 제휴·승인받은 서비스가 아닙니다.</strong> 공개된 지원사업 정보를 보기 쉽게 정리하고 각 제공기관의 공식 공고와 접수처로 연결하는 독립 서비스입니다.</p><a class="portal-link" href="https://www.bizinfo.go.kr/" target="_blank" rel="noopener noreferrer"><div><strong>기업마당 공식 공고</strong><small>중소벤처기업부·중소벤처기업진흥공단 운영 공식 출처</small></div>${icon('external','sm')}</a><h3>${dataState.mode==='live'?'공개 공고 통합 수집본':'공고 자료 불러오는 중'}</h3><p>${sourceLabel()}<br>기업마당 공고와 네이버 공개 전체 목록의 지난 공고까지 수집합니다. 원천 제공 건수와 중복 제거 통합 건수는 구분합니다. 수집 실패 시 이전 성공 자료를 유지합니다.</p><button class="btn soft spaced" data-action="data-connect">공고 갱신 상태 ${icon('arrow','sm')}</button><h3>추천 방식</h3><p>확인된 조건만 대조합니다. API 공고의 지역·분야는 검색 분류이며 실제 신청 자격을 뜻하지 않습니다. 지원 한도·상환·제외업종·선정 여부는 원문 확인이 필요합니다.</p><h3>내 정보 보관</h3><p>사업 프로필, 관심사업, 체크리스트, 메모는 이 브라우저에 보관합니다. 검색과 맞춤 조건 비교도 이 브라우저에서 처리합니다. 사업 정보와 메모를 서버로 전송하지 않습니다. 기기 간 개인 기록 동기화는 제공하지 않습니다.</p><a class="portal-link" href="./privacy.html"><div><strong>개인정보처리방침</strong><small>앱과 웹사이트의 데이터 처리 기준</small></div>${icon('chevron','sm')}</a><button class="text-btn spaced" data-action="guide">데이터 백업·이용 가이드 ${icon('arrow','sm')}</button>`);}

function save(id){if(!known.has(id))return;const exists=state.saved.includes(id);state.saved=exists?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();renderResults();if(activeDetail)details(activeDetail);toast(exists?'관심 저장을 해제했습니다. 준비 기록은 보관됩니다.':'관심사업에 저장했습니다. 신청 준비에서 체크하세요.');}
function download(content,filename,type){const blob=new Blob([content],{type});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
async function share(id){const p=programs.find(p=>p.id===id),u=new URL(location.href);u.search='';u.searchParams.set('notice',id);try{if(navigator.share){await navigator.share({title:p.title,text:'지원한눈 · '+p.benefit,url:u.href});}else{await navigator.clipboard.writeText(u.href);toast('공유 링크를 복사했습니다. 현재 앱은 소유자 비공개 배포입니다.');}}catch(err){if(err.name!=='AbortError')showDialog('공유 링크',`<p class="dialog-subtitle">링크를 복사해 보관하세요. 현재 앱은 소유자 비공개 배포입니다.</p><label class="field"><span class="field-label">공고 링크</span><input value="${e(u.href)}" readonly onclick="this.select()"></label>`);}}
function closeDialog(){dialogLayers.closeParent();activeDetail=null;urlUpdate();}
document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;
  if(action==='nav')navigate(b.dataset.view);
  else if(action==='find')navigate('browse');
  else if(action==='detail')details(id);
  else if(action==='profile')profileDialog();
  else if(action==='new-profile')profileDialog(true);
  else if(action==='close')closeDialog();
  else if(action==='close-viewer')dialogLayers.closeViewer();
  else if(action==='save')save(id);
  else if(action==='metric'){
    const scrollY=window.scrollY;filters=metricFilters(b.dataset.value);view='browse';activeDetail=null;pendingTagFeedback=null;pendingMetricFeedback=b.dataset.value;dialogLayers.closeParent();urlUpdate();syncSearchControls();toast(`${metricLabels[b.dataset.value]} 공고를 조회합니다.`);renderResults();window.scrollTo({top:scrollY,behavior:'instant'});
  }
  else if(action==='category'){filters.category=b.dataset.value;filters.subcategory='전체';document.querySelector('#category-tabs').innerHTML=categoryTabs();document.querySelector('#filter-subcategory').innerHTML=subcategoryOptions();renderResults();urlUpdate();}
  else if(action==='tag'){
    if(ev.metaKey||ev.ctrlKey||ev.shiftKey||ev.altKey||ev.button!==0)return;ev.preventDefault();
    const scrollY=window.scrollY,sameView=view==='browse';
    filters={region:'전체',type:'전체',purpose:'전체',category:'전체',subcategory:'전체',query:'',tag:b.dataset.tag,status:'current',sort:'latest',matched:false};view='browse';activeDetail=null;page=1;pendingTagFeedback=filters.tag;dialogLayers.closeParent();history.pushState({},'',b.href);
    toast(`#${filters.tag} 태그로 조회 중…`);if(sameView){syncSearchControls();renderResults();}else render();window.scrollTo({top:scrollY,behavior:'instant'});
  }
  else if(action==='clear-tag'){const scrollY=window.scrollY;filters.tag='';pendingTagFeedback=null;document.querySelector('#tag-filter').innerHTML='';urlUpdate();renderResults();window.scrollTo({top:scrollY,behavior:'instant'});toast('태그 조건을 해제했습니다.');}
  else if(action==='document-view'){
    const p=programs.find(p=>p.id===id),f=normalizeAttachments(p?.attachments)[Number(b.dataset.index)],viewer=officialViewer(f?.viewerUrl);if(!viewer)return;
    showViewer('문서 바로보기',`<p class="document-name">${e(f.name)}</p><iframe class="document-preview" src="${e(viewer)}" title="${e(f.name)} 문서 뷰어" referrerpolicy="no-referrer" sandbox="allow-scripts allow-same-origin allow-forms allow-downloads allow-popups"></iframe><p class="viewer-help">문서 화면이 보이지 않으면 새 창 보기를 이용하세요.</p>`,`<button class="btn secondary" data-action="close-viewer">상세로 돌아가기</button><a class="btn secondary" href="${e(viewer)}" target="_blank" rel="noopener noreferrer">새 창 보기 ↗</a><a class="btn primary" href="${e(f.downloadUrl||f.url)}" target="_blank" rel="noopener noreferrer" download="${e(f.name)}">다운로드</a>`,b);
  }
  else if(action==='attachment'){
    const p=programs.find(p=>p.id===id),f=normalizeAttachments(p?.attachments)[Number(b.dataset.index)],url=publicUrl(f?.url);if(!url||!f.pdf)return;
    if(!dialog.open||activeDetail!==id)return;
    showViewer('공고문 PDF',`<p class="dialog-subtitle">${e(f.name)}</p><div id="pdf-content" class="pdf-status" role="status">PDF를 불러오고 있습니다…</div>`,`<button class="btn secondary" data-action="close-viewer">상세로 돌아가기</button><a class="btn primary" href="${e(url)}" target="_blank" rel="noopener noreferrer">원본 열기 ↗</a>`,b);
    const controller=new AbortController();pdfController=controller;
    try{
      const preview=await attachmentPreview(id,Number(b.dataset.index));if(controller.signal.aborted||!viewerDialog.open||pdfController!==controller)return;if(!preview)throw Error('저장된 PDF가 없습니다. 공식 원본에서 확인하세요.');
      const r=await fetch(preview,{signal:controller.signal,cache:'no-store'});
      if(!r.ok||!r.headers.get('content-type')?.includes('application/pdf'))throw Error('미리보기를 불러오지 못했습니다. 원본 열기로 공식 파일을 확인하세요.');
      const blob=await r.blob();if(controller.signal.aborted||!viewerDialog.open||pdfController!==controller)return;
      pdfObjectUrl=URL.createObjectURL(blob);viewerDialog.querySelector('#pdf-content').innerHTML=`<iframe class="pdf-preview" src="${pdfObjectUrl}" title="${e(f.name)}"></iframe>`;
    }catch(error){if(error.name==='AbortError'||pdfController!==controller)return;const content=viewerDialog.querySelector('#pdf-content');if(content)content.innerHTML=`<div class="pdf-error">${icon('info')}<h3>공식 원본에서 확인하세요</h3><p>${e(error.message)}</p><a class="btn primary small" href="${e(url)}" target="_blank" rel="noopener noreferrer">PDF 원본 열기 ↗</a></div>`;}
  }
  else if(action==='purpose'){filters.purpose=b.dataset.value;document.querySelectorAll('[data-action="purpose"]').forEach(c=>{c.classList.toggle('active',c.dataset.value===filters.purpose);c.setAttribute('aria-pressed',String(c.dataset.value===filters.purpose));});renderResults();urlUpdate();}
  else if(action==='reset-filters'){const scrollY=window.scrollY;filters={...metricFilters('all'),status:'current'};pendingMetricFeedback=null;pendingTagFeedback=null;syncSearchControls();document.querySelector('#tag-filter').innerHTML='';urlUpdate();renderResults();window.scrollTo({top:scrollY,behavior:'instant'});toast('조회 조건을 초기화했습니다.');}
  else if(action==='compare-clear'){compared=[];render();renderResults();}
  else if(action==='compare-open')compareDialog();
  else if(action==='calendar')calendarDialog();
  else if(action==='data-info')dataDialog();
  else if(action==='data-connect')connectDialog();
  else if(action==='sync-now')syncNow();
  else if(action==='refresh-status'){await loadStatus();connectDialog();}
  else if(action==='retry-search')renderResults(false);
  else if(action==='page'){page=Number(b.dataset.page);renderResults(false);document.querySelector('.results-toolbar')?.scrollIntoView({behavior:'smooth',block:'start'});}
  else if(action==='guide'){closeDialog();navigate('guide');}
  else if(action==='start-prepare'){if(!state.saved.includes(id))state.saved.push(id);state.records[id]={...record(id),status:record(id).status==='관심'?'준비중':record(id).status};persist();closeDialog();navigate('prepare');toast('신청 준비에 추가했습니다.');}
  else if(action==='ics'){const p=programs.find(p=>p.id===id);if(!p?.end)return;download(buildCalendar(p),`지원한눈_${p.title}_마감.ics`,'text/calendar;charset=utf-8');toast('캘린더 파일을 저장했습니다. 캘린더 앱에서 가져오세요.');}
  else if(action==='share')share(id);
  else if(action==='delete-profile'){state.profiles=state.profiles.filter(p=>p.id!==id);state.activeProfile=state.profiles[0]?.id||null;filters.matched=false;persist();closeDialog();render();renderResults();toast('사업 정보를 삭제했습니다.');}
  else if(action==='backup'){download(JSON.stringify({schema:'jiwonhannun-v1',exportedAt:new Date().toISOString(),...state},null,2),`지원한눈_내기록_${koreanDate()}.json`,'application/json');toast('백업 파일을 저장했습니다. 사업 정보가 포함되어 있어요.');}
  else if(action==='import')document.querySelector('#import-file').click();
  else if(action==='clear-data'){if(window.confirm('사업 프로필, 관심사업, 준비 기록을 모두 삭제할까요? 백업하지 않은 기록은 복구할 수 없습니다.')){state=emptyStore();persist();render();toast('이 브라우저의 저장 데이터를 삭제했습니다.');}}
  else if(action==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else{showDialog('홈 화면에 추가',`<p>Android Chrome: 브라우저 메뉴에서 <strong>홈 화면에 추가</strong> 또는 <strong>앱 설치</strong>를 선택하세요.</p><p class="spaced">iPhone Safari: 공유 버튼 → <strong>홈 화면에 추가</strong>를 선택하세요.</p><p class="muted tiny spaced">설치 메뉴는 브라우저 및 배포 인증 환경에 따라 달라질 수 있습니다.</p>`);}}
  else if(action==='compare-export'){const list=compared.map(id=>programs.find(p=>p.id===id));const cell=s=>'"'+String(s).replaceAll('"','""')+'"';download('\uFEFF'+[['사업명','유형','지역','지원내용','자부담','상환','접수기간','공식원문'],...list.map(p=>[p.title,p.type,p.city||p.region,p.benefit,p.cost,p.repayment,period(p),p.sourceUrl])].map(row=>row.map(cell).join(',')).join('\r\n'),'지원한눈_지원사업비교.csv','text/csv;charset=utf-8');}
});
document.addEventListener('input',ev=>{if(ev.target.id==='query'){filters.query=ev.target.value;renderResults();urlUpdate();}if(ev.target.matches('[data-notes]')){const id=ev.target.dataset.notes;state.records[id]={...record(id),notes:ev.target.value};persist();}});
document.addEventListener('change',async ev=>{const t=ev.target;
  if(t.id==='profile-switch'){state.activeProfile=t.value;persist();render();renderResults();}
  if(['filter-region','filter-type','filter-subcategory','filter-status','sort','matched-only'].includes(t.id)){const key={'filter-region':'region','filter-type':'type','filter-subcategory':'subcategory','filter-status':'status',sort:'sort','matched-only':'matched'}[t.id];filters[key]=t.id==='matched-only'?t.checked:t.value;renderResults();urlUpdate();}
  if(t.dataset.compare){const id=t.dataset.compare;if(t.checked&&compared.length>=3){t.checked=false;toast('한 번에 최대 3개 사업을 비교할 수 있어요.');return;}compared=t.checked?[...new Set([...compared,id])]:compared.filter(x=>x!==id);document.querySelector('#compare-container').innerHTML=tray();renderResults();}
  if(t.dataset.recordStatus){const id=t.dataset.recordStatus;state.records[id]={...record(id),status:t.value};persist();toast('신청 상태를 저장했습니다.');}
  if(t.dataset.check){const id=t.dataset.id,r=record(id);state.records[id]={...r,checks:t.checked?[...new Set([...r.checks,t.dataset.check])]:r.checks.filter(c=>c!==t.dataset.check)};persist();render();}
  if(t.id==='import-file'){const file=t.files?.[0];if(!file)return;if(file.size>1000000){toast('1MB 이하의 지원한눈 백업 파일을 선택하세요.');return;}try{const data=JSON.parse(await file.text());if(data.schema!=='jiwonhannun-v1')throw Error('지원한눈 백업 파일이 아닙니다.');const next=normalizeStore(data);if(!window.confirm('현재 기록을 백업 파일의 기록으로 교체할까요?'))return;state=next;persist();render();toast('백업 기록을 가져왔습니다.');}catch(err){toast('가져오기 실패: '+err.message);}}
});
document.addEventListener('submit',ev=>{const f=ev.target;ev.preventDefault();if(f.id==='search-form'){renderResults();return;}if(f.id==='profile-form'){const v=Object.fromEntries(new FormData(f));v.name=v.name.trim();v.city=v.city.trim();if(!v.name){toast('사업 별명을 입력하세요.');return;}if(v.opened&&v.opened>koreanDate()){toast('개업일을 확인해 주세요.');return;}v.id=v.id||crypto.randomUUID();const ix=state.profiles.findIndex(p=>p.id===v.id);if(ix>=0)state.profiles[ix]=v;else state.profiles.push(v);state.activeProfile=v.id;persist();closeDialog();view='browse';filters={region:v.region,type:'전체',purpose:'전체',category:'전체',subcategory:'전체',query:'',status:'current',sort:'match',matched:true};urlUpdate();render();renderResults();toast('내 사업과 관련된 지원을 찾았습니다. 추가 조건도 확인하세요.');}else if(f.id==='loan-form')calculate('loan');else if(f.id==='subsidy-form')calculate('subsidy');});
window.addEventListener('popstate',()=>{const q=new URLSearchParams(location.search);view=navItems.some(n=>n[0]===q.get('view'))?q.get('view'):'browse';filters.query=q.get('q')||'';filters.tag=q.get('tag')?.slice(0,100)||'';filters.region=regions.includes(q.get('region'))?q.get('region'):'전체';filters.type=types.includes(q.get('type'))?q.get('type'):'전체';filters.purpose=purposes.includes(q.get('purpose'))?q.get('purpose'):'전체';filters.category=categories.includes(q.get('category'))?q.get('category'):'전체';filters.subcategory=q.get('subcategory')?.slice(0,100)||'전체';filters.status=['current','open','urgent','upcoming','unknown','all','closed'].includes(q.get('status'))?q.get('status'):'current';dialogLayers.closeParent();render();renderResults();if(q.get('notice'))details(q.get('notice'));});
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev;});
window.addEventListener('storage',ev=>{if(ev.key===KEY){try{state=ev.newValue?normalizeStore(JSON.parse(ev.newValue)):emptyStore();render();renderResults();}catch{toast('다른 탭의 기록을 불러올 수 없습니다.');}}});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();renderResults();initializeData();

function sourceLabel(){return dataState.mode==='live'?`마지막 수집 ${formatTime(dataState.lastSuccess)}`:`초기 자료 ${DATA_DATE.replaceAll('-','.')} · 전체 수집 대기`;}
function formatTime(value){return value?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',dateStyle:'short',timeStyle:'short'}).format(new Date(value)):'아직 없음';}
function dataBanner(){const issue=dataError||dataState.lastRun?.error||dataState.bizinfoError;return `<section class="data-banner ${issue||dataState.stale?'warning':''}" aria-label="공고 수집 상태"><div>${icon('layers')}<div><strong>${dataState.mode==='live'?`${dataState.catalog?'통합 공고':'기업마당 API 현재 수집본'} ${dataState.count.toLocaleString('ko-KR')}건`:'전체 공고를 연결하세요'}</strong><p>${issue?e(issue):dataState.running?'공고 수집 중입니다. 이전 자료를 보여드립니다.':dataState.mode==='live'?`${sourceLabel()}${dataState.stale?' · 갱신 지연':''}${dataState.catalog?` · 네이버 원천 전체 ${dataState.catalog.npaySourceCount.toLocaleString('ko-KR')}건 / 진행중 ${dataState.catalog.npayActiveCount.toLocaleString('ko-KR')}건 · 통합 검색은 중복 제거 기준`:' · 전국 모든 기관·과거 전체 건수가 아닙니다.'}`:'공고 자료를 불러오는 중입니다. 잠시 후 다시 확인해 주세요.'}</p></div></div><button class="btn secondary small" data-action="data-connect">${dataState.connected?'갱신 상태':'공고 갱신 상태'}${icon('chevron','sm')}</button></section>`;}
function mergePrograms(list){for(const p of list){const index=programs.findIndex(x=>x.id===p.id);if(index>=0)programs[index]=p;else programs.push(p);known.add(p.id);}}
async function loadStatus(){try{dataState=await api('/api/data-status');serverReady=true;dataError='';return true;}catch(err){dataError=err.message;return false;}}
async function hydrateSaved(){const ids=[...new Set([...state.saved,...Object.keys(state.records),...(query.get('notice')?[query.get('notice')]:[])])];if(!ids.length)return;for(let i=0;i<ids.length;i+=200){try{const r=await api('/api/notices',{ids:ids.slice(i,i+200)});for(const p of r.programs){if(p.requestedId&&p.requestedId!==p.id){noticeAliases.set(p.requestedId,p.id);state.saved=[...new Set(state.saved.map(id=>id===p.requestedId?p.id:id))];if(state.records[p.requestedId]&&!state.records[p.id])state.records[p.id]=state.records[p.requestedId];}}mergePrograms(r.programs);persist();}catch{toast('일부 관심사업의 원문 자료를 불러오지 못했습니다. 저장한 준비 기록은 유지됩니다.');break;}}}
async function initializeData(){await loadStatus();await hydrateSaved();render();if(query.get('notice')){const id=noticeAliases.get(query.get('notice'))||query.get('notice');if(known.has(id))details(id);else toast('공고 자료를 찾지 못했습니다. 공식 원문을 확인해 주세요.');}}
function connectDialog(){activeDetail=null;showDialog('공고 갱신 상태',`<p class="dialog-subtitle">매일 공고를 수집해 갱신합니다. 검색은 마지막으로 완료된 수집본을 사용합니다.</p><dl class="sync-summary"><div><dt>통합 공고</dt><dd>${dataState.count.toLocaleString('ko-KR')}건</dd></div><div><dt>마지막 갱신</dt><dd>${formatTime(dataState.lastSuccess)}</dd></div><div><dt>예약 갱신</dt><dd>매일 06:17 · 한국시간</dd></div><div><dt>상세 수집</dt><dd>${(dataState.detailCount||0).toLocaleString('ko-KR')}건 · 미수집 상세는 공식 원문 연결</dd></div><div><dt>기업마당 자료</dt><dd>${formatTime(dataState.bizinfoLastSuccess)}${dataState.bizinfoError?' · 이전 성공본 사용':''}</dd></div></dl>${dataState.bizinfoError?`<p class="info-notice">${e(dataState.bizinfoError)}</p>`:''}<p class="muted spaced">예약 작업이 지연되거나 수집이 실패하면 이전 성공 자료를 유지합니다. 첨부파일은 원본 링크를 제공하고, 저장된 PDF는 바로 볼 수 있습니다.</p>`,`<button class="btn primary" data-action="sync-now">최신 배포 자료 확인</button><a class="btn secondary" href="https://github.com/softm/softm.policyfundfinder/actions" target="_blank" rel="noopener noreferrer">갱신 실행 내역 ↗</a>`);}
async function syncNow(){if(syncing)return;syncing=true;try{dataState=await refreshData();await hydrateSaved();render();connectDialog();toast('배포된 최신 공고 자료를 확인했습니다.');}catch(error){toast(error.message);}finally{syncing=false;}}
